<?php $labels = ['draft' => 'Borrador', 'scheduled' => 'Programada', 'running' => 'En proceso', 'paused' => 'Pausada', 'completed' => 'Completada', 'failed' => 'Con errores', 'cancelled' => 'Cancelada']; ?>
<div class="table-responsive"><table class="table align-middle"><thead><tr><th>Campaña</th><th>Canales</th><th>Estado</th><th>Programación</th><th class="text-end">Acciones</th></tr></thead><tbody>
<?php if ($campaigns === []): ?><tr><td colspan="5" class="text-center text-body-secondary py-5">No hay campañas para mostrar.</td></tr><?php endif; ?>
<?php foreach ($campaigns as $campaign): $channels = json_decode((string)($campaign['channels_json'] ?? '[]'), true) ?: []; $status = (string)($campaign['status'] ?? 'draft'); ?>
<tr><td><strong><?= htmlspecialchars((string)$campaign['name'], ENT_QUOTES, 'UTF-8') ?></strong><div class="small text-body-secondary"><?= htmlspecialchars((string)$campaign['title'], ENT_QUOTES, 'UTF-8') ?></div></td><td><?= htmlspecialchars(implode(', ', $channels), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($labels[$status] ?? $status, ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string)($campaign['scheduled_at'] ?? 'Inmediata'), ENT_QUOTES, 'UTF-8') ?></td><td class="text-end"><div class="btn-group btn-group-sm"><?php if ($status === 'paused'): ?><button class="btn btn-outline-primary" type="button" data-campaign-action="resume" data-campaign-id="<?= (int)$campaign['campaign_id'] ?>">Reanudar</button><?php elseif (!in_array($status, ['completed', 'cancelled'], true)): ?><button class="btn btn-outline-secondary" type="button" data-campaign-action="pause" data-campaign-id="<?= (int)$campaign['campaign_id'] ?>">Pausar</button><button class="btn btn-outline-primary" type="button" data-campaign-action="run" data-campaign-id="<?= (int)$campaign['campaign_id'] ?>">Procesar lote</button><button class="btn btn-outline-danger" type="button" data-campaign-action="cancel" data-campaign-id="<?= (int)$campaign['campaign_id'] ?>">Cancelar</button><?php endif; ?></div></td></tr>
<?php endforeach; ?></tbody></table></div>
<?php PaginationHelper::render((int)($meta['total_pages'] ?? 1), (int)($meta['page'] ?? 1)); ?>
